from collections import deque

def candidate(a,conn=4,edge=True,noncomp=True):
 h=len(a);w=len(a[0]); seeds=[(r,c) for r in range(h) for c in range(w) if a[r][c]==6]
 seen=set(seeds); q=deque(seeds)
 dirs=[(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and a[rr][cc]==8 and (rr,cc) not in seen:
    seen.add((rr,cc));q.append((rr,cc))
 out=[row[:] for row in a]
 for r,c in seen:
  if a[r][c]!=8: continue
  boundary=False
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   rr,cc=r+dr,c+dc
   if rr<0 or rr>=h or cc<0 or cc>=w:
    boundary |= edge
   elif (rr,cc) not in seen:
    boundary |= noncomp
  if boundary: out[r][c]=7
 return out,seen
for k,(a,b) in enumerate(pairs,1):
 out,seen=candidate(a)
 print('demo',k,'match cells',sum(x==y for ro,rb in zip(out,b) for x,y in zip(ro,rb)),'/',len(a)**2,'diffs',[(r,c,a[r][c],b[r][c],out[r][c]) for r in range(len(a)) for c in range(len(a)) if b[r][c]!=out[r][c]][:30])

def candidate2(a,conn=4, boundary_conn=8, edge=True, remove_unselected=True):
 h=len(a);w=len(a[0]); seeds=[(r,c) for r in range(h) for c in range(w) if a[r][c]==6]
 seen=set(seeds); q=deque(seeds)
 dirs=[(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and a[rr][cc]==8 and (rr,cc) not in seen:
    seen.add((rr,cc));q.append((rr,cc))
 out=[row[:] for row in a]
 bdirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc] if boundary_conn==8 else dirs
 for r in range(h):
  for c in range(w):
   if a[r][c]==1 and remove_unselected:
    # preserve iff adjacent to reachable region or in source seed neighborhood?
    if not any((r+dr,c+dc) in seen for dr,dc in bdirs): out[r][c]=8
   elif a[r][c]==8 and (r,c) in seen:
    if any((r+dr,c+dc) not in seen or not(0<=r+dr<h and 0<=c+dc<w) for dr,dc in bdirs): out[r][c]=7
 return out,seen
for k,(a,b) in enumerate(pairs,1):
 for conn in (4,8):
  out,seen=candidate2(a,conn=conn,boundary_conn=8)
  diff=[(r,c,a[r][c],b[r][c],out[r][c]) for r in range(len(a)) for c in range(len(a)) if b[r][c]!=out[r][c]]
  print(k,conn,'match',len(a)**2-len(diff),'diffs',diff[:30])

def candidate3(a,conn=4,boundary_conn=8):
 h=len(a);w=len(a[0]); seeds=[(r,c) for r in range(h) for c in range(w) if a[r][c]==6]
 seen=set(seeds); q=deque(seeds); d4=[(1,0),(-1,0),(0,1),(0,-1)]; d8=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
 dirs=d4 if conn==4 else d8
 while q:
