 # determine color1 components to retain if any cell adjacent 8-neighbor to reachable component
 ones=set((r,c) for r in range(h) for c in range(w) if a[r][c]==1);keep=set();
 while ones:
  start=ones.pop();comp={start};qq=[start]
  for r,c in qq:
